//! The `.isa` text form of PrismIR: printer and parser.
//!
//! The ISA is PrismIR's canonical spelling — the golden-test format
//! and the base every target lowering reads — so unlike the MIR dump
//! it must round-trip: `parse(print(p))` prints identically.
//!
//! ```text
//! ; prism ISA — generated by glcc -fprism --emit-isa
//! shader @fs_main : fragment
//!   dcl.input   v0 : float2 semantic(TEXCOORD0)
//!   dcl.output  o0 : float4 semantic(COLOR0)
//!   dcl.uniform u0 name(tint) c5=float4
//!   dcl.sampler s0 name(tex)
//!   %0 : float4 = sample s0, v0
//!   %1 : pred = setp.gt %0.x, 0.5
//!   if %1 {
//!     %2 : float = add %0.y, %0.z
//!   } else {
//!     %3 : float = sub %0.y, %0.z
//!   }
//!   %4 : float = phi [%2, then], [%3, else]
//!   ret %4
//! ```
//!
//! Sources spell registers with swizzles and a `-` negate prefix,
//! inputs as `v<n>`, uniforms as `u<object>.c<reg>` (+ lane, + `[c<n>]`
//! for relative indexing), constants as literals, undefined values as
//! `undef`. Every `phi` carries its full incoming list: `then`/`else`
//! after an `if`, `entry` plus one `continue.K` per continue inside a
//! loop body (carried registers), and one `break.K` per break after a
//! loop (exit registers). Register types are printed at each
//! definition; register ids are absolute, so the parser can type them
//! in any order.

use std::format;
use std::string::{String, ToString};
use std::vec::Vec;

use smallvec::{smallvec, SmallVec};

use crate::interface::{Interface, InterfaceLeaf, SamplerVar, UniformLeaf, UniformVar};
use crate::ir::{Alu, Body, CmpCode, Lod, Op, Program, RegTy, Scalar, Setp, Src, Stage, Stmt, Swizzle, Tex, VReg};

// ---------------------------------------------------------------------
// printer

/// Render one program as `.isa` text.
pub fn print(program: &Program) -> String {
    let mut out = String::new();
    out.push_str("; prism ISA — generated by glcc -fprism --emit-isa\n");
    out.push_str(&format!("shader @{} : {}\n", program.name, program.stage.mnemonic()));
    for (index, leaf) in program.interface.inputs.iter().enumerate() {
        out.push_str(&format!("  dcl.input v{index} : {} semantic({})\n", ty_text(&leaf.ty), leaf.semantic));
    }
    for (index, leaf) in program.interface.outputs.iter().enumerate() {
        out.push_str(&format!("  dcl.output o{index} : {} semantic({})\n", ty_text(&leaf.ty), leaf.semantic));
    }
    for (index, uniform) in program.interface.uniforms.iter().enumerate() {
        let leaves = uniform
            .leaves
            .iter()
            .map(|leaf| {
                let lane = if leaf.ty.lanes() == 1 {
                    format!(".{}", lane_char(leaf.lane))
                } else {
                    String::new()
                };
                format!("c{}{}={}", leaf.creg, lane, ty_text(&leaf.ty))
            })
            .collect::<Vec<_>>()
            .join(", ");
        out.push_str(&format!("  dcl.uniform u{index} name({}) {}\n", uniform.name, leaves));
    }
    for (index, sampler) in program.interface.samplers.iter().enumerate() {
        out.push_str(&format!("  dcl.sampler s{index} name({})\n", sampler.name));
    }
    print_body(&program.body, 1, program, &mut out);
    out
}

fn print_body(body: &Body, depth: usize, program: &Program, out: &mut String) {
    for stmt in &body.stmts {
        print_stmt(stmt, depth, program, out);
    }
}

fn print_stmt(stmt: &Stmt, depth: usize, program: &Program, out: &mut String) {
    match stmt {
        Stmt::Op(op) => {
            indent(depth, out);
            let ty = program.reg_ty(op.dst);
            out.push_str(&format!("%{} : {} = {}\n", op.dst.0, ty_text(&ty), alu_text(op)));
        }
        Stmt::Tex(tex) => {
            indent(depth, out);
            let ty = program.reg_ty(tex.dst);
            let lod = match tex.lod {
                Lod::Implicit => String::new(),
                Lod::Explicit(level) => format!(", lod({level})"),
            };
            out.push_str(&format!(
                "%{} : {} = sample s{}, {}{}\n",
                tex.dst.0,
                ty_text(&ty),
                tex.sampler,
                src_text(&tex.coord),
                lod
            ));
        }
        Stmt::Setp(setp) => {
            indent(depth, out);
            out.push_str(&format!(
                "%{} : pred = setp.{} {}, {}\n",
                setp.dst.0,
                setp.code.mnemonic(),
                src_text(&setp.a),
                src_text(&setp.b)
            ));
        }
        Stmt::If { pred, then, els, results } => {
            indent(depth, out);
            let joins = results.iter().map(|(join, _, _)| format!("%{}", join.0)).collect::<Vec<_>>().join(", ");
            out.push_str(&format!("if %{} ->{} {{\n", pred.0, if joins.is_empty() { String::new() } else { format!(" {joins}") }));
            print_body(then, depth + 1, program, out);
            if els.stmts.is_empty() {
                indent(depth, out);
                out.push_str("}\n");
            } else {
                indent(depth, out);
                out.push_str("} else {\n");
                print_body(els, depth + 1, program, out);
                indent(depth, out);
                out.push_str("}\n");
            }
            for (join, then_v, else_v) in results {
                indent(depth, out);
                let ty = program.reg_ty(*join);
                out.push_str(&format!(
                    "%{} : {} = phi [%{}, then], [%{}, else]\n",
                    join.0,
                    ty_text(&ty),
                    then_v.0,
                    else_v.0
                ));
            }
        }
        Stmt::Loop { carried, body: loop_body, results } => {
            indent(depth, out);
            let exits = results.iter().map(|v| format!("%{}", v.0)).collect::<Vec<_>>().join(", ");
            out.push_str(&format!("loop ->{} {{\n", if exits.is_empty() { String::new() } else { format!(" {exits}") }));
            // Carried registers read as phis with one `entry` incoming
            // plus one per `continue`, in body order.
            let continues = collect_controls(loop_body).continues;
            for (slot, (phi, init)) in carried.iter().enumerate() {
                indent(depth + 1, out);
                let ty = program.reg_ty(*phi);
                out.push_str(&format!("%{} : {} = phi {}\n", phi.0, ty_text(&ty), carried_incoming(slot, init, &continues)));
            }
            print_body(loop_body, depth + 1, program, out);
            indent(depth, out);
            out.push_str("}\n");
            let breaks = collect_controls(loop_body).breaks;
            for (index, result) in results.iter().enumerate() {
                indent(depth, out);
                let ty = program.reg_ty(*result);
                let incoming = breaks
                    .iter()
                    .enumerate()
                    .map(|(order, args)| {
                        let value = args.get(index).or_else(|| args.last()).copied().unwrap_or(*result);
                        format!("[%{}, break.{}]", value.0, order)
                    })
                    .collect::<Vec<_>>()
                    .join(", ");
                out.push_str(&format!("%{} : {} = phi {}\n", result.0, ty_text(&ty), incoming));
            }
        }
        Stmt::Break(args) => {
            indent(depth, out);
            out.push_str(&format!("break{}\n", args_text(args)));
        }
        Stmt::Continue(args) => {
            indent(depth, out);
            out.push_str(&format!("continue{}\n", args_text(args)));
        }
        Stmt::Exit(outputs) => {
            indent(depth, out);
            out.push_str(&format!("ret{}\n", args_text(outputs)));
        }
    }
}

/// The carried phi's incoming list: the init value at `entry`, then
/// each continue's argument for this slot, in body order.
fn carried_incoming(slot: usize, init: &VReg, continues: &[SmallVec<[VReg; 4]>]) -> String {
    let mut text = format!("[%{}, entry]", init.0);
    for (order, args) in continues.iter().enumerate() {
        let value = args.get(slot).or_else(|| args.last()).copied().unwrap_or(*init);
        text.push_str(&format!(", [%{}, continue.{}]", value.0, order));
    }
    text
}

/// (breaks, continues) of a body, pre-order — for the structurizer
/// tests.
#[cfg(test)]
pub fn test_controls_of(body: &Body) -> (usize, usize) {
    let controls = collect_controls(body);
    (controls.breaks.len(), controls.continues.len())
}

/// Break and continue statements of one loop body, in pre-order.
fn collect_controls(body: &Body) -> Controls {
    let mut controls = Controls::default();
    collect_into(body, &mut controls);
    controls
}

#[derive(Default)]
struct Controls {
    breaks: Vec<SmallVec<[VReg; 4]>>,
    continues: Vec<SmallVec<[VReg; 4]>>,
}

fn collect_into(body: &Body, controls: &mut Controls) {
    for stmt in &body.stmts {
        match stmt {
            Stmt::Break(args) => controls.breaks.push(args.clone()),
            Stmt::Continue(args) => controls.continues.push(args.clone()),
            Stmt::If { then, els, .. } => {
                collect_into(then, controls);
                collect_into(els, controls);
            }
            Stmt::Loop { body: inner, .. } => collect_into(inner, controls),
            _ => {}
        }
    }
}

fn indent(depth: usize, out: &mut String) {
    for _ in 0..depth {
        out.push_str("  ");
    }
}

fn args_text(args: &[VReg]) -> String {
    if args.is_empty() {
        String::new()
    } else {
        format!(" {}", args.iter().map(|v| format!("%{}", v.0)).collect::<Vec<_>>().join(", "))
    }
}

fn ty_text(ty: &RegTy) -> &'static str {
    match ty {
        RegTy::Scalar(Scalar::F32) => "float",
        RegTy::Scalar(Scalar::Int { bits }) => match bits {
            8 => "i8",
            16 => "i16",
            _ => "i32",
        },
        RegTy::Vector { elem, lanes } => match (elem, lanes) {
            (Scalar::F32, 2) => "float2",
            (Scalar::F32, 3) => "float3",
            (Scalar::F32, _) => "float4",
            (Scalar::Int { bits: 8 }, 2) => "i8x2",
            (Scalar::Int { bits: 8 }, 3) => "i8x3",
            (Scalar::Int { bits: 8 }, _) => "i8x4",
            (Scalar::Int { bits: 16 }, 2) => "i16x2",
            (Scalar::Int { bits: 16 }, 3) => "i16x3",
            (Scalar::Int { bits: 16 }, _) => "i16x4",
            (_, 2) => "i32x2",
            (_, 3) => "i32x3",
            (_, _) => "i32x4",
        },
        RegTy::Pred => "pred",
    }
}

fn alu_text(op: &Op) -> String {
    let name = match &op.kind {
        Alu::Mov => "mov",
        Alu::Add => "add",
        Alu::Sub => "sub",
        Alu::Mul => "mul",
        Alu::Mad => "mad",
        Alu::IDiv { unsigned: false } => "sdiv",
        Alu::IDiv { unsigned: true } => "udiv",
        Alu::IRem { unsigned: false } => "srem",
        Alu::IRem { unsigned: true } => "urem",
        Alu::Rcp => "rcp",
        Alu::Rsq => "rsq",
        Alu::Sqrt => "sqrt",
        Alu::Floor => "floor",
        Alu::Ceil => "ceil",
        Alu::Frac => "frc",
        Alu::Abs => "abs",
        Alu::Neg => "neg",
        Alu::Min => "min",
        Alu::Max => "max",
        Alu::Dp3 => "dp3",
        Alu::Dp4 => "dp4",
        Alu::Cmp(code) => return format!("cmp.{} {}", code.mnemonic(), srcs_text(&op.srcs)),
        Alu::Zext => "zext",
        Alu::Sext => "sext",
        Alu::Trunc => "trunc",
        Alu::IToF { unsigned: false } => "sitof",
        Alu::IToF { unsigned: true } => "uitof",
        Alu::FToI { unsigned: false } => "ftosi",
        Alu::FToI { unsigned: true } => "ftoui",
        Alu::Bitcast => "bitcast",
        Alu::And => "and",
        Alu::Or => "or",
        Alu::Xor => "xor",
        Alu::Not => "not",
        Alu::Shl => "shl",
        Alu::Shr { arithmetic: false } => "lshr",
        Alu::Shr { arithmetic: true } => "ashr",
        Alu::Sel => "sel",
        Alu::Shuffle { lanes } => return format!("shuffle {} [{}]", srcs_text(&op.srcs), lanes_text(lanes)),
    };
    format!("{name} {}", srcs_text(&op.srcs))
}

fn srcs_text(srcs: &[Src]) -> String {
    srcs.iter().map(src_text).collect::<Vec<_>>().join(", ")
}

fn lanes_text(lanes: &[u8]) -> String {
    lanes.iter().map(|l| l.to_string()).collect::<Vec<_>>().join(",")
}

/// Spell one source operand: `-` negate prefix, then the register
/// form with its swizzle.
fn src_text(src: &Src) -> String {
    let (negate, body) = match src {
        Src::VReg { v, swizzle, negate } => (*negate, reg_swizzle(&format!("%{}", v.0), swizzle.as_ref())),
        Src::ConstF32(value) => (false, const_f32_text(*value)),
        Src::ConstI32(value) => (false, value.to_string()),
        Src::Undef => (false, "undef".to_string()),
        Src::Input { input, swizzle, negate } => (*negate, reg_swizzle(&format!("v{input}"), swizzle.as_ref())),
        Src::Uniform { object, reg, swizzle, negate, rel } => {
            let rel = rel.map(|v| format!("[c{}]", v.0)).unwrap_or_default();
            (*negate, format!("u{object}.c{reg}{rel}{}", swizzle_suffix(swizzle.as_ref())))
        }
    };
    if negate {
        format!("-{body}")
    } else {
        body
    }
}

fn reg_swizzle(reg: &str, swizzle: Option<&Swizzle>) -> String {
    format!("{reg}{}", swizzle_suffix(swizzle))
}

fn swizzle_suffix(swizzle: Option<&Swizzle>) -> String {
    match swizzle {
        None => String::new(),
        Some(lanes) => format!(".{}", lanes.iter().map(|&l| lane_char(l)).collect::<String>()),
    }
}

fn lane_char(lane: u8) -> char {
    match lane {
        0 => 'x',
        1 => 'y',
        2 => 'z',
        _ => 'w',
    }
}

fn const_f32_text(value: f32) -> String {
    if value.is_nan() {
        "nan".to_string()
    } else if value.is_infinite() {
        if value < 0.0 { "-inf".to_string() } else { "inf".to_string() }
    } else {
        format!("{value}")
    }
}

// ---------------------------------------------------------------------
// parser

/// Parse `.isa` text back into a program. The text must have been
/// produced by [`print`] (or match its grammar exactly); errors carry
/// the line number.
pub fn parse(text: &str) -> Result<Program, String> {
    let mut parser = Parser::new(text);
    parser.parse_program()
}

struct Parser {
    tokens: Vec<(Token, usize)>,
    pos: usize,
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Newline,
    Ident(String),
    /// `%<number>` — a virtual register or predicate.
    VReg(u32),
    /// `v<number>` — an input register.
    Input(u32),
    /// `c<number>` — a c-register.
    CReg(u32),
    /// `u<number>` — a uniform object.
    Uniform(u32),
    /// `s<number>` — a sampler.
    Sampler(u32),
    /// `o<number>` — an output slot.
    Output(u32),
    Float(f32),
    Int(i32),
    Symbol(char),
}

impl Parser {
    fn new(text: &str) -> Parser {
        let mut tokens = Vec::new();
        let mut line = 1usize;
        let mut chars = text.chars().peekable();
        while let Some(&ch) = chars.peek() {
            match ch {
                '\n' => {
                    tokens.push((Token::Newline, line));
                    line += 1;
                    chars.next();
                }
                ' ' | '\t' | '\r' => {
                    chars.next();
                }
                ';' => {
                    while let Some(&c) = chars.peek() {
                        if c == '\n' {
                            break;
                        }
                        chars.next();
                    }
                }
                _ => {
                    let token = lex_token(&mut chars);
                    tokens.push((token, line));
                }
            }
        }
        Parser { tokens, pos: 0 }
    }

    fn err(&self, message: &str) -> String {
        let line = self.tokens.get(self.pos).map(|(_, l)| *l).unwrap_or(0);
        format!("prism isa: line {line}: {message}")
    }

    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos).map(|(t, _)| t)
    }

    fn bump(&mut self) -> Option<Token> {
        let token = self.tokens.get(self.pos).map(|(t, _)| t.clone());
        if token.is_some() {
            self.pos += 1;
        }
        token
    }

    fn eat_newlines(&mut self) {
        while matches!(self.peek(), Some(Token::Newline)) {
            self.pos += 1;
        }
    }

    fn expect_symbol(&mut self, ch: char) -> Result<(), String> {
        match self.bump() {
            Some(Token::Symbol(c)) if c == ch => Ok(()),
            other => Err(self.err(&format!("expected '{ch}', got {other:?}"))),
        }
    }

    fn expect_keyword(&mut self, keyword: &str) -> Result<(), String> {
        match self.bump() {
            Some(Token::Ident(text)) if text == keyword => Ok(()),
            other => Err(self.err(&format!("expected '{keyword}', got {other:?}"))),
        }
    }

    fn peek_keyword(&self, keyword: &str) -> bool {
        matches!(self.peek(), Some(Token::Ident(text)) if text == keyword)
    }

    fn parse_program(&mut self) -> Result<Program, String> {
        self.eat_newlines();
        self.expect_keyword("shader")?;
        self.expect_symbol('@')?;
        let name = match self.bump() {
            Some(Token::Ident(name)) => name,
            other => return Err(self.err(&format!("expected the shader name, got {other:?}"))),
        };
        self.expect_symbol(':')?;
        let stage = match self.bump() {
            Some(Token::Ident(stage)) => match stage.as_str() {
                "vertex" => Stage::Vertex,
                "fragment" => Stage::Fragment,
                other => return Err(self.err(&format!("unknown stage '{other}'"))),
            },
            other => return Err(self.err(&format!("expected a stage, got {other:?}"))),
        };
        let mut interface = Interface {
            stage,
            entry: name.clone(),
            inputs: Vec::new(),
            outputs: Vec::new(),
            uniforms: Vec::new(),
            samplers: Vec::new(),
        };
        loop {
            self.eat_newlines();
            if self.peek_keyword("dcl") {
                self.parse_dcl(&mut interface)?;
            } else {
                break;
            }
        }
        let mut program = Program {
            name,
            stage,
            interface,
            regs: Vec::new(),
            body: Body::new(),
        };
        program.body = self.parse_body(0, &mut program)?;
        Ok(program)
    }

    fn parse_dcl(&mut self, interface: &mut Interface) -> Result<(), String> {
        self.expect_keyword("dcl")?;
        // The printer spells `dcl.input`; accept the bare form too.
        if matches!(self.peek(), Some(Token::Symbol('.'))) {
            self.expect_symbol('.')?;
        }
        let kind = match self.bump() {
            Some(Token::Ident(kind)) => kind,
            other => return Err(self.err(&format!("expected a declaration kind, got {other:?}"))),
        };
        match kind.as_str() {
            "input" | "output" => {
                let class = if kind == "input" { TokenClass::Input } else { TokenClass::Output };
                let index = self.expect_reg(class)?;
                self.expect_symbol(':')?;
                let ty = self.parse_ty()?;
                let semantic = self.expect_semantic()?;
                let leaf = InterfaceLeaf { semantic, ty };
                let list = if kind == "input" { &mut interface.inputs } else { &mut interface.outputs };
                if index as usize != list.len() {
                    return Err(self.err(&format!("{kind} registers must be declared in order")));
                }
                list.push(leaf);
            }
            "uniform" => {
                let index = self.expect_reg(TokenClass::Uniform)?;
                self.expect_keyword("name")?;
                self.expect_symbol('(')?;
                let name = match self.bump() {
                    Some(Token::Ident(name)) => name,
                    other => return Err(self.err(&format!("expected the uniform name, got {other:?}"))),
                };
                self.expect_symbol(')')?;
                let mut leaves = Vec::new();
                while matches!(self.peek(), Some(Token::CReg(_))) {
                    let reg = match self.bump() {
                        Some(Token::CReg(reg)) => reg,
                        _ => unreachable!("peeked"),
                    };
                    let lane = if matches!(self.peek(), Some(Token::Symbol('.'))) {
                        self.expect_symbol('.')?;
                        self.expect_lane()?
                    } else {
                        0
                    };
                    self.expect_symbol('=')?;
                    let ty = self.parse_ty()?;
                    leaves.push(UniformLeaf {
                        path: Vec::new(),
                        ty,
                        creg: reg as u8,
                        lane,
                        std140_offset: 0,
                    });
                    if matches!(self.peek(), Some(Token::Symbol(','))) {
                        self.expect_symbol(',')?;
                    } else {
                        break;
                    }
                }
                if index as usize != interface.uniforms.len() {
                    return Err(self.err("uniforms must be declared in order"));
                }
                interface.uniforms.push(UniformVar {
                    name,
                    creg: leaves.first().map(|leaf| leaf.creg).unwrap_or(0),
                    leaves,
                    std140_size: 0,
                });
            }
            "sampler" => {
                let index = self.expect_reg(TokenClass::Sampler)?;
                self.expect_keyword("name")?;
                self.expect_symbol('(')?;
                let name = match self.bump() {
                    Some(Token::Ident(name)) => name,
                    other => return Err(self.err(&format!("expected the sampler name, got {other:?}"))),
                };
                self.expect_symbol(')')?;
                if index as usize != interface.samplers.len() {
                    return Err(self.err("samplers must be declared in order"));
                }
                interface.samplers.push(SamplerVar { name });
            }
            other => return Err(self.err(&format!("unknown declaration kind '{other}'"))),
        }
        Ok(())
    }

    fn expect_semantic(&mut self) -> Result<String, String> {
        self.expect_keyword("semantic")?;
        self.expect_symbol('(')?;
        let name = match self.bump() {
            Some(Token::Ident(name)) => name,
            other => return Err(self.err(&format!("expected a semantic name, got {other:?}"))),
        };
        self.expect_symbol(')')?;
        Ok(name)
    }

    fn expect_lane(&mut self) -> Result<u8, String> {
        match self.bump() {
            Some(Token::Ident(text)) if text.len() == 1 => match text.as_str() {
                "x" => Ok(0),
                "y" => Ok(1),
                "z" => Ok(2),
                "w" => Ok(3),
                other => Err(self.err(&format!("unknown lane '{other}'"))),
            },
            other => Err(self.err(&format!("expected a lane, got {other:?}"))),
        }
    }

    fn expect_reg(&mut self, class: TokenClass) -> Result<u32, String> {
        match self.bump() {
            Some(token) if class.matches(&token) => Ok(reg_number(&token).expect("class matched")),
            other => Err(self.err(&format!("expected a {}, got {other:?}", class.name()))),
        }
    }

    fn parse_ty(&mut self) -> Result<RegTy, String> {
        match self.bump() {
            Some(Token::Ident(text)) => ty_from_text(&text).ok_or_else(|| self.err(&format!("unknown type '{text}'"))),
            other => Err(self.err(&format!("expected a type, got {other:?}"))),
        }
    }

    /// Statements until the closing brace at `depth` (or end of input
    /// at depth 0), consuming the brace. Regions nest (a loop body
    /// holds ifs, a loop nest holds loops), so pending regions form a
    /// stack; region joins ride `phi` statements: an `if`'s follow it
    /// (then/else labels), a loop's carried phis lead its body
    /// (entry/continue labels) and its exit phis follow its closing
    /// brace (break labels).
    fn parse_body(&mut self, depth: usize, program: &mut Program) -> Result<Body, String> {
        enum Region {
            /// An `if` awaiting its declared join phis.
            If {
                pred: u32,
                then: Body,
                els: Body,
                joins: Vec<u32>,
                results: Vec<(VReg, VReg, VReg)>,
            },
            /// A `loop`: body statements until its `}`, then its
            /// declared exit phis (`collected` gathers them).
            Loop {
                carried: Vec<(VReg, VReg)>,
                body: Body,
                closed: bool,
                exits: Vec<u32>,
                collected: Vec<VReg>,
            },
        }
        let mut body = Body::new();
        let mut stack: Vec<Region> = Vec::new();
        // Build a pending region's statement (its phis collected).
        fn region_stmt(region: Region) -> Result<Stmt, String> {
            Ok(match region {
                Region::If { pred, then, els, joins, results } => {
                    if results.len() != joins.len() {
                        return Err(format!("an if is missing its declared join phis ({} of {})", results.len(), joins.len()));
                    }
                    Stmt::If { pred: VReg(pred), then, els, results }
                }
                Region::Loop {
                    carried,
                    body,
                    closed: _,
                    exits,
                    collected,
                } => Stmt::Loop {
                    carried,
                    body,
                    results: if collected.is_empty() { exits.into_iter().map(VReg).collect() } else { collected },
                },
            })
        }
        // Route a statement: into the innermost open loop's body, or —
        // after flushing whatever is pending — into the enclosing
        // body.
        macro_rules! route {
            ($stmt:expr) => {{
                let stmt = $stmt;
                let lands_in_loop = matches!(stack.last(), Some(Region::Loop { closed: false, .. }));
                if !lands_in_loop {
                    while let Some(top) = stack.last() {
                        if matches!(top, Region::Loop { closed: false, .. }) {
                            break;
                        }
                        let region = stack.pop().expect("checked");
                        let stmt = region_stmt(region)?;
                        match stack.last_mut() {
                            Some(Region::Loop { body: inner, closed: false, .. }) => inner.stmts.push(stmt),
                            _ => body.stmts.push(stmt),
                        }
                    }
                }
                match stack.last_mut() {
                    Some(Region::Loop { body: inner, closed: false, .. }) => inner.stmts.push(stmt),
                    _ => body.stmts.push(stmt),
                }
            }};
        }
        loop {
            self.eat_newlines();
            let peeked = self.peek().cloned();
            match peeked {
                None => {
                    if depth > 0 && !stack.is_empty() {
                        return Err(self.err("unexpected end of input inside a region"));
                    }
                    // Flush any pending regions into the body.
                    while let Some(region) = stack.pop() {
                        let stmt = region_stmt(region)?;
                        match stack.last_mut() {
                            Some(Region::Loop { body: inner, closed: false, .. }) => inner.stmts.push(stmt),
                            _ => body.stmts.push(stmt),
                        }
                    }
                    return Ok(body);
                }
                Some(Token::Symbol('}')) => {
                    if stack.is_empty() {
                        if depth == 0 {
                            return Err(self.err("unexpected '}'"));
                        }
                        // The enclosing arm's closing brace.
                        self.pos += 1;
                        return Ok(body);
                    }
                    self.pos += 1;
                    // Braces close loops; an `if` owns no brace of its
                    // own (its arms were parsed recursively), so a `}`
                    // under a pending if first flushes the if, then
                    // closes the loop it sits in.
                    match stack.last_mut() {
                        Some(Region::Loop { closed, .. }) if !*closed => {
                            *closed = true;
                            continue;
                        }
                        _ => {}
                    }
                    if stack.is_empty() {
                        return Ok(body);
                    }
                    // Flush the pending region into its parent, then
                    // close the loop this brace belongs to.
                    let region = stack.pop().expect("checked");
                    let stmt = region_stmt(region)?;
                    match stack.last_mut() {
                        Some(Region::Loop { body: inner, closed: false, .. }) => inner.stmts.push(stmt),
                        _ => body.stmts.push(stmt),
                    }
                    match stack.last_mut() {
                        Some(Region::Loop { closed, .. }) if !*closed => *closed = true,
                        _ => return Ok(body),
                    }
                }
                Some(Token::Ident(word)) if word == "if" => {
                    self.pos += 1;
                    let pred = self.expect_reg(TokenClass::VReg)?;
                    program.set_reg_ty(VReg(pred), RegTy::Pred)?;
                    // The if declares its join registers up front, so
                    // each following phi has an unambiguous owner.
                    let mut joins = Vec::new();
                    if matches!(self.peek(), Some(Token::Symbol('-'))) {
                        self.expect_symbol('-')?;
                        self.expect_symbol('>')?;
                        while matches!(self.peek(), Some(Token::VReg(_))) {
                            let join = self.expect_reg(TokenClass::VReg)?;
                            let ty = if matches!(self.peek(), Some(Token::Symbol(':'))) {
                                self.expect_symbol(':')?;
                                Some(self.parse_ty()?)
                            } else {
                                None
                            };
                            if let Some(ty) = ty {
                                program.set_reg_ty(VReg(join), ty)?;
                            }
                            joins.push(join);
                            if matches!(self.peek(), Some(Token::Symbol(','))) {
                                self.expect_symbol(',')?;
                            } else {
                                break;
                            }
                        }
                    }
                    self.expect_symbol('{')?;
                    let then = self.parse_body(depth + 1, program)?;
                    let els = if self.peek_keyword("else") {
                        self.pos += 1;
                        self.expect_symbol('{')?;
                        self.parse_body(depth + 1, program)?
                    } else {
                        Body::new()
                    };
                    stack.push(Region::If {
                        pred,
                        then,
                        els,
                        joins,
                        results: Vec::new(),
                    });
                }
                Some(Token::Ident(word)) if word == "loop" => {
                    self.pos += 1;
                    // The loop declares its exit registers up front.
                    let mut exits = Vec::new();
                    if matches!(self.peek(), Some(Token::Symbol('-'))) {
                        self.expect_symbol('-')?;
                        self.expect_symbol('>')?;
                        while matches!(self.peek(), Some(Token::VReg(_))) {
                            let exit = self.expect_reg(TokenClass::VReg)?;
                            if matches!(self.peek(), Some(Token::Symbol(':'))) {
                                self.expect_symbol(':')?;
                                let ty = self.parse_ty()?;
                                program.set_reg_ty(VReg(exit), ty)?;
                            }
                            exits.push(exit);
                            if matches!(self.peek(), Some(Token::Symbol(','))) {
                                self.expect_symbol(',')?;
                            } else {
                                break;
                            }
                        }
                    }
                    self.expect_symbol('{')?;
                    stack.push(Region::Loop {
                        carried: Vec::new(),
                        body: Body::new(),
                        closed: false,
                        exits,
                        collected: Vec::new(),
                    });
                }
                Some(Token::VReg(_)) => {
                    // A definition: an operation — or a phi joining a
                    // region.
                    let dst = self.expect_reg(TokenClass::VReg)?;
                    self.expect_symbol(':')?;
                    let ty = self.parse_ty()?;
                    program.set_reg_ty(VReg(dst), ty)?;
                    self.expect_symbol('=')?;
                    let keyword = match self.bump() {
                        Some(Token::Ident(word)) => word,
                        other => return Err(self.err(&format!("expected an operation, got {other:?}"))),
                    };
                    if keyword == "phi" {
                        let incomings = self.parse_incomings()?;
                        let labels = incomings.iter().map(|(label, _)| *label).collect::<Vec<_>>();
                        // Attach to the topmost region still wanting
                        // its declared phis (inner regions that declared
                        // none are skipped).
                        let wants = |region: &Region| match region {
                            Region::If { joins, results, .. } => results.len() < joins.len(),
                            // An open loop always takes carried phis; a
                            // closed one takes its declared exit phis.
                            Region::Loop { closed, exits, collected, .. } => {
                                if *closed {
                                    collected.len() < exits.len()
                                } else {
                                    true
                                }
                            }
                        };
                        let target = stack.iter_mut().rev().find(|region| wants(region));
                        match target {
                            Some(Region::If { results, .. }) => {
                                if labels.as_slice() != ["then", "else"] {
                                    return Err(self.err("an if join takes exactly two incomings (then, else)"));
                                }
                                results.push((VReg(dst), VReg(incomings[0].1), VReg(incomings[1].1)));
                            }
                            Some(Region::Loop { carried, closed, exits, collected, .. }) => {
                                if !*closed {
                                    if labels.first() != Some(&"entry") {
                                        return Err(self.err("a carried phi leads with its entry incoming"));
                                    }
                                    if labels.iter().skip(1).any(|label| *label != "continue") {
                                        return Err(self.err("carried phi incomings after entry must be continues"));
                                    }
                                    carried.push((VReg(dst), VReg(incomings[0].1)));
                                } else {
                                    if labels.iter().any(|label| *label != "break") {
                                        return Err(self.err("loop exit phi labels must be breaks"));
                                    }
                                    collected.push(VReg(dst));
                                }
                            }
                            None => return Err(self.err("a phi with no region to join")),
                        }
                        continue;
                    }
                    let stmt = self.parse_defined(dst, &keyword, program)?;
                    route!(stmt);
                }
                Some(Token::Ident(word)) if word == "phi" => {
                    return Err(self.err("a phi definition starts with its register"));
                }
                Some(Token::Ident(word)) if matches!(word.as_str(), "break" | "continue" | "ret") => {
                    self.pos += 1;
                    let mut args = SmallVec::new();
                    while matches!(self.peek(), Some(Token::VReg(_))) {
                        args.push(VReg(self.expect_reg(TokenClass::VReg)?));
                        if matches!(self.peek(), Some(Token::Symbol(','))) {
                            self.expect_symbol(',')?;
                        } else {
                            break;
                        }
                    }
                    let stmt = match word.as_str() {
                        "break" => Stmt::Break(args),
                        "continue" => Stmt::Continue(args),
                        _ => Stmt::Exit(args.into_iter().collect()),
                    };
                    route!(stmt);
                }
                Some(_) => {
                    return Err(self.err("expected a statement"));
                }
            }
        }
    }

    /// The incoming list of a phi: `[%v, label], [%v, label.K], ...`
    fn parse_incomings(&mut self) -> Result<Vec<(&'static str, u32)>, String> {
        let mut incomings = Vec::new();
        loop {
            self.expect_symbol('[')?;
            if self.eat_negate()? {
                return Err(self.err("phi incoming values are registers"));
            }
            let value = self.expect_reg(TokenClass::VReg)?;
            self.expect_symbol(',')?;
            let label = match self.bump() {
                Some(Token::Ident(label)) => match label.as_str() {
                    "then" | "else" | "entry" | "continue" | "break" => label,
                    other => return Err(self.err(&format!("unknown phi label '{other}'"))),
                },
                other => return Err(self.err(&format!("expected a phi label, got {other:?}"))),
            };
            if matches!(self.peek(), Some(Token::Symbol('.'))) {
                self.expect_symbol('.')?;
                match self.bump() {
                    Some(Token::Int(_)) => {}
                    other => return Err(self.err(&format!("expected a label index, got {other:?}"))),
                }
            }
            let owned: &'static str = match label.as_str() {
                "then" => "then",
                "else" => "else",
                "entry" => "entry",
                "continue" => "continue",
                _ => "break",
            };
            self.expect_symbol(']')?;
            incomings.push((owned, value));
            if matches!(self.peek(), Some(Token::Symbol(','))) {
                self.expect_symbol(',')?;
            } else {
                break;
            }
        }
        Ok(incomings)
    }

    fn eat_negate(&mut self) -> Result<bool, String> {
        if matches!(self.peek(), Some(Token::Symbol('-'))) {
            self.pos += 1;
            return Ok(true);
        }
        Ok(false)
    }

    /// The tail of an operation statement after `%dst : ty =`:
    /// `sample`, `setp.<code>`, or an ALU mnemonic.
    fn parse_defined(&mut self, dst: u32, keyword: &str, program: &mut Program) -> Result<Stmt, String> {
        match keyword {
            "sample" => {
                let sampler = self.expect_reg(TokenClass::Sampler)?;
                self.expect_symbol(',')?;
                let coord = self.parse_src()?;
                let lod = if matches!(self.peek(), Some(Token::Symbol(','))) {
                    self.expect_symbol(',')?;
                    self.expect_keyword("lod")?;
                    self.expect_symbol('(')?;
                    let level = match self.bump() {
                        Some(Token::Float(f)) => f,
                        other => return Err(self.err(&format!("expected a lod level, got {other:?}"))),
                    };
                    self.expect_symbol(')')?;
                    Lod::Explicit(level)
                } else {
                    Lod::Implicit
                };
                Ok(Stmt::Tex(Tex { dst: VReg(dst), sampler, coord, lod }))
            }
            "setp" => {
                self.expect_symbol('.')?;
                let code = self.parse_cmp_code()?;
                let a = self.parse_src()?;
                self.expect_symbol(',')?;
                let b = self.parse_src()?;
                Ok(Stmt::Setp(Setp { dst: VReg(dst), code, a, b }))
            }
            "cmp" => {
                self.expect_symbol('.')?;
                let code = self.parse_cmp_code()?;
                let mut srcs = SmallVec::new();
                loop {
                    srcs.push(self.parse_src()?);
                    if matches!(self.peek(), Some(Token::Symbol(','))) {
                        self.expect_symbol(',')?;
                    } else {
                        break;
                    }
                }
                Ok(Stmt::Op(Op { dst: VReg(dst), kind: Alu::Cmp(code), srcs }))
            }
            word => {
                let kind = alu_from_text(word)
                    .ok_or_else(|| self.err(&format!("unknown operation '{word}'")))?;
                let mut srcs = SmallVec::new();
                loop {
                    srcs.push(self.parse_src()?);
                    if matches!(self.peek(), Some(Token::Symbol(','))) {
                        self.expect_symbol(',')?;
                    } else {
                        break;
                    }
                }
                let kind = match kind {
                    ParsedAlu::Simple(kind) => kind,
                    ParsedAlu::Shuffle => {
                        self.expect_symbol('[')?;
                        let mut lanes = SmallVec::new();
                        loop {
                            match self.bump() {
                                Some(Token::Int(lane)) => lanes.push(lane as u8),
                                other => return Err(self.err(&format!("expected a lane index, got {other:?}"))),
                            }
                            if matches!(self.peek(), Some(Token::Symbol(','))) {
                                self.expect_symbol(',')?;
                            } else {
                                break;
                            }
                        }
                        self.expect_symbol(']')?;
                        Alu::Shuffle { lanes }
                    }
                };
                Ok(Stmt::Op(Op { dst: VReg(dst), kind, srcs }))
            }
        }
    }

    fn parse_cmp_code(&mut self) -> Result<CmpCode, String> {
        match self.bump() {
            Some(Token::Ident(text)) => match text.as_str() {
                "lt" => Ok(CmpCode::Lt),
                "le" => Ok(CmpCode::Le),
                "gt" => Ok(CmpCode::Gt),
                "ge" => Ok(CmpCode::Ge),
                "eq" => Ok(CmpCode::Eq),
                "ne" => Ok(CmpCode::Ne),
                other => Err(self.err(&format!("unknown comparison '{other}'"))),
            },
            other => Err(self.err(&format!("expected a comparison, got {other:?}"))),
        }
    }

    fn parse_src(&mut self) -> Result<Src, String> {
        let negate = self.eat_negate()?;
        let mut src = match self.bump() {
            Some(Token::VReg(v)) => Src::VReg { v: VReg(v), swizzle: self.maybe_swizzle()?, negate: false },
            Some(Token::Input(v)) => Src::Input { input: v, swizzle: self.maybe_swizzle()?, negate: false },
            Some(Token::Uniform(object)) => {
                self.expect_symbol('.')?;
                let reg = self.expect_reg(TokenClass::CReg)?;
                let rel = if matches!(self.peek(), Some(Token::Symbol('['))) {
                    self.expect_symbol('[')?;
                    let index = self.expect_reg(TokenClass::CReg)?;
                    self.expect_symbol(']')?;
                    Some(VReg(index))
                } else {
                    None
                };
                Src::Uniform { object, reg: reg as u8, swizzle: self.maybe_swizzle()?, negate: false, rel }
            }
            Some(Token::Float(f)) => Src::ConstF32(f),
            Some(Token::Int(i)) => Src::ConstI32(i),
            Some(Token::Ident(word)) if word == "undef" => Src::Undef,
            other => return Err(self.err(&format!("expected a source operand, got {other:?}"))),
        };
        if negate {
            src = negate_src(src);
        }
        Ok(src)
    }

    fn maybe_swizzle(&mut self) -> Result<Option<Swizzle>, String> {
        if !matches!(self.peek(), Some(Token::Symbol('.'))) {
            return Ok(None);
        }
        // A `.` may start a swizzle or a label index (`continue.0` is
        // lexed as its own tokens, so this is safe here).
        self.expect_symbol('.')?;
        let mut lanes = Swizzle::new();
        // The lexer folds `.xyzw` into one identifier; 1-4 lane
        // characters form the swizzle.
        if let Some(Token::Ident(text)) = self.peek().cloned() {
            if (1..=4).contains(&text.len()) && text.chars().all(|c| matches!(c, 'x' | 'y' | 'z' | 'w')) {
                for c in text.chars() {
                    lanes.push(match c {
                        'x' => 0,
                        'y' => 1,
                        'z' => 2,
                        _ => 3,
                    });
                }
                self.pos += 1;
            }
        }
        if lanes.is_empty() {
            return Err(self.err("expected a swizzle after '.'"));
        }
        Ok(Some(lanes))
    }
}

enum ParsedAlu {
    Simple(Alu),
    Shuffle,
}

fn alu_from_text(text: &str) -> Option<ParsedAlu> {
    Some(match text {
        "mov" => ParsedAlu::Simple(Alu::Mov),
        "add" => ParsedAlu::Simple(Alu::Add),
        "sub" => ParsedAlu::Simple(Alu::Sub),
        "mul" => ParsedAlu::Simple(Alu::Mul),
        "mad" => ParsedAlu::Simple(Alu::Mad),
        "sdiv" => ParsedAlu::Simple(Alu::IDiv { unsigned: false }),
        "udiv" => ParsedAlu::Simple(Alu::IDiv { unsigned: true }),
        "srem" => ParsedAlu::Simple(Alu::IRem { unsigned: false }),
        "urem" => ParsedAlu::Simple(Alu::IRem { unsigned: true }),
        "rcp" => ParsedAlu::Simple(Alu::Rcp),
        "rsq" => ParsedAlu::Simple(Alu::Rsq),
        "sqrt" => ParsedAlu::Simple(Alu::Sqrt),
        "floor" => ParsedAlu::Simple(Alu::Floor),
        "ceil" => ParsedAlu::Simple(Alu::Ceil),
        "frc" => ParsedAlu::Simple(Alu::Frac),
        "abs" => ParsedAlu::Simple(Alu::Abs),
        "neg" => ParsedAlu::Simple(Alu::Neg),
        "min" => ParsedAlu::Simple(Alu::Min),
        "max" => ParsedAlu::Simple(Alu::Max),
        "dp3" => ParsedAlu::Simple(Alu::Dp3),
        "dp4" => ParsedAlu::Simple(Alu::Dp4),
        "zext" => ParsedAlu::Simple(Alu::Zext),
        "sext" => ParsedAlu::Simple(Alu::Sext),
        "trunc" => ParsedAlu::Simple(Alu::Trunc),
        "sitof" => ParsedAlu::Simple(Alu::IToF { unsigned: false }),
        "uitof" => ParsedAlu::Simple(Alu::IToF { unsigned: true }),
        "ftosi" => ParsedAlu::Simple(Alu::FToI { unsigned: false }),
        "ftoui" => ParsedAlu::Simple(Alu::FToI { unsigned: true }),
        "bitcast" => ParsedAlu::Simple(Alu::Bitcast),
        "and" => ParsedAlu::Simple(Alu::And),
        "or" => ParsedAlu::Simple(Alu::Or),
        "xor" => ParsedAlu::Simple(Alu::Xor),
        "not" => ParsedAlu::Simple(Alu::Not),
        "shl" => ParsedAlu::Simple(Alu::Shl),
        "lshr" => ParsedAlu::Simple(Alu::Shr { arithmetic: false }),
        "ashr" => ParsedAlu::Simple(Alu::Shr { arithmetic: true }),
        "sel" => ParsedAlu::Simple(Alu::Sel),
        "shuffle" => ParsedAlu::Shuffle,
        _ => return None,
    })
}

fn negate_src(src: Src) -> Src {
    match src {
        Src::VReg { v, swizzle, negate } => Src::VReg { v, swizzle, negate: !negate },
        Src::Input { input, swizzle, negate } => Src::Input { input, swizzle, negate: !negate },
        Src::Uniform { object, reg, swizzle, negate, rel } => Src::Uniform { object, reg, swizzle, negate: !negate, rel },
        Src::ConstF32(value) => Src::ConstF32(-value),
        Src::ConstI32(value) => Src::ConstI32(-value),
        Src::Undef => Src::Undef,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TokenClass {
    VReg,
    Input,
    CReg,
    Uniform,
    Sampler,
    Output,
}

impl TokenClass {
    fn name(&self) -> &'static str {
        match self {
            TokenClass::VReg => "register",
            TokenClass::Input => "input register",
            TokenClass::CReg => "c-register",
            TokenClass::Uniform => "uniform object",
            TokenClass::Sampler => "sampler",
            TokenClass::Output => "output slot",
        }
    }

    fn matches(&self, token: &Token) -> bool {
        matches!(
            (self, token),
            (TokenClass::VReg, Token::VReg(_))
                | (TokenClass::Input, Token::Input(_))
                | (TokenClass::CReg, Token::CReg(_))
                | (TokenClass::Uniform, Token::Uniform(_))
                | (TokenClass::Sampler, Token::Sampler(_))
                | (TokenClass::Output, Token::Output(_))
        )
    }
}

fn reg_number(token: &Token) -> Option<u32> {
    match token {
        Token::VReg(n) | Token::Input(n) | Token::CReg(n) | Token::Uniform(n) | Token::Sampler(n) | Token::Output(n) => Some(*n),
        _ => None,
    }
}

fn ty_from_text(text: &str) -> Option<RegTy> {
    Some(match text {
        "float" => RegTy::Scalar(Scalar::F32),
        "i8" => RegTy::Scalar(Scalar::Int { bits: 8 }),
        "i16" => RegTy::Scalar(Scalar::Int { bits: 16 }),
        "i32" => RegTy::Scalar(Scalar::i32()),
        "pred" => RegTy::Pred,
        "float2" => RegTy::Vector { elem: Scalar::F32, lanes: 2 },
        "float3" => RegTy::Vector { elem: Scalar::F32, lanes: 3 },
        "float4" => RegTy::Vector { elem: Scalar::F32, lanes: 4 },
        "i8x2" => RegTy::Vector { elem: Scalar::Int { bits: 8 }, lanes: 2 },
        "i8x3" => RegTy::Vector { elem: Scalar::Int { bits: 8 }, lanes: 3 },
        "i8x4" => RegTy::Vector { elem: Scalar::Int { bits: 8 }, lanes: 4 },
        "i16x2" => RegTy::Vector { elem: Scalar::Int { bits: 16 }, lanes: 2 },
        "i16x3" => RegTy::Vector { elem: Scalar::Int { bits: 16 }, lanes: 3 },
        "i16x4" => RegTy::Vector { elem: Scalar::Int { bits: 16 }, lanes: 4 },
        "i32x2" => RegTy::Vector { elem: Scalar::i32(), lanes: 2 },
        "i32x3" => RegTy::Vector { elem: Scalar::i32(), lanes: 3 },
        "i32x4" => RegTy::Vector { elem: Scalar::i32(), lanes: 4 },
        _ => return None,
    })
}

fn lex_token(chars: &mut core::iter::Peekable<core::str::Chars<'_>>) -> Token {
    let Some(first) = chars.peek().copied() else { return Token::Newline };
    chars.next();
    match first {
        '%' => Token::VReg(lex_number(chars).unwrap_or(u32::MAX)),
        'v' if chars.peek().is_some_and(|c| c.is_ascii_digit()) => Token::Input(lex_number(chars).unwrap_or(u32::MAX)),
        'c' if chars.peek().is_some_and(|c| c.is_ascii_digit()) => Token::CReg(lex_number(chars).unwrap_or(u32::MAX)),
        'u' if chars.peek().is_some_and(|c| c.is_ascii_digit()) => Token::Uniform(lex_number(chars).unwrap_or(u32::MAX)),
        's' if chars.peek().is_some_and(|c| c.is_ascii_digit()) => Token::Sampler(lex_number(chars).unwrap_or(u32::MAX)),
        'o' if chars.peek().is_some_and(|c| c.is_ascii_digit()) => Token::Output(lex_number(chars).unwrap_or(u32::MAX)),
        '0'..='9' => {
            let mut text = String::new();
            text.push(first);
            while let Some(&c) = chars.peek() {
                if c.is_ascii_alphanumeric() || c == '.' || c == '_' {
                    text.push(c);
                    chars.next();
                } else if (c == '+' || c == '-') && (text.ends_with('e') || text.ends_with('E')) {
                    text.push(c);
                    chars.next();
                } else {
                    break;
                }
            }
            if text.contains('.') || text.contains('e') || text.contains('E') {
                Token::Float(text.parse::<f32>().unwrap_or(f32::NAN))
            } else {
                Token::Int(text.parse::<i32>().unwrap_or(i32::MAX))
            }
        }
        '-' => Token::Symbol('-'),
        ch if ch.is_ascii_alphabetic() || ch == '_' => {
            let mut text = String::new();
            text.push(ch);
            while let Some(&c) = chars.peek() {
                if c.is_ascii_alphanumeric() || c == '_' {
                    text.push(c);
                    chars.next();
                } else {
                    break;
                }
            }
            Token::Ident(text)
        }
        ch => Token::Symbol(ch),
    }
}

fn lex_number(chars: &mut core::iter::Peekable<core::str::Chars<'_>>) -> Option<u32> {
    let mut text = String::new();
    while let Some(&c) = chars.peek() {
        if c.is_ascii_digit() {
            text.push(c);
            chars.next();
        } else {
            break;
        }
    }
    text.parse().ok()
}
